 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    blocks = []
    for r in range(h - 1):
        for c in range(w - 1):
            if all(grid[rr][cc] == 2 for rr in (r, r + 1) for cc in (c, c + 1)):
                blocks.append((r, c))
    for r, c in blocks:
        pts = [(r-1,c-1,-1,-1), (r-1,c+2,-1,1),
               (r+2,c-1,1,-1), (r+2,c+2,1,1)]
        vals = [grid[a][b] if 0 <= a < h and 0 <= b < w else 0 for a,b,_,_ in pts]
        # Cycle corner colors: bottom-left -> top-left -> top-right -> bottom-right -> bottom-left.
        colors = [vals[2], vals[0], vals[3], vals[1]]
        for (a,b,dr,dc), color in zip(pts, colors):
            if color == 0 or not (0 <= a < h and 0 <= b < w):
